package com.aicharacter.v3;
public final class PersistentLifeDiagnostics{private PersistentLifeDiagnostics(){}
 public static String persistence(WorldState s){int undelivered=0;for(GodMessage m:s.godInbox)if(!m.delivered)undelivered++;return"PERSISTENCE TRACE\nsaveVersion="+WorldState.SAVE_VERSION+" lastSimulatedAt="+s.lastSimulatedAt+"\ncat="+s.catState.sleepMode+" area="+s.catState.areaId+" x="+(int)s.catState.x+" attached="+s.catState.attachedToEntity+" knownCarried="+s.catState.carryKnownByGirl+"\ngirl area="+HaruPerception.currentPlaceId(s)+" x="+(int)s.haruX+" intention="+s.currentIntention+"\nsearch active="+s.catSearch.active+" paused="+s.catSearch.paused+" index="+s.catSearch.index+"\nGod pending="+undelivered+" inbox="+s.godInbox.size();}
 public static String sleep(WorldState s){StringBuilder b=new StringBuilder("CAT SLEEP TRACE\n");for(CatSleepPlanner.Plan p:CatSleepPlanner.candidates(s))b.append(p.mode).append(" score=").append(String.format(java.util.Locale.US,"%.3f",p.score)).append(" dest=").append(p.areaId).append(" reason=").append(p.reason).append('\n');return b.append("chosen/current=").append(s.catState.sleepMode).append(" route=").append(s.catTravel.route).append(" arrivalArea=").append(s.catState.sleepAreaId).append(" attach=").append(CatOfflineEngine.attachTrace(s)).toString();}
 public static String god(WorldState s){StringBuilder b=new StringBuilder("GOD ATTENTION TRACE\n").append(s.lastGodTrace).append('\n');for(int i=Math.max(0,s.godInbox.size()-8);i<s.godInbox.size();i++){GodMessage m=s.godInbox.get(i);b.append(m.messageId).append(" source=").append(m.sourceEventId).append(" grounded=").append(GodAttentionEngine.grounded(s,m)).append(" delivered=").append(m.delivered).append(" text=").append(m.text).append('\n');}return b.toString();}
}
